episodes.settled_cypher:
/*+ INDEX(owner1:Person(id), owner2:Company(id), owner1:Company(id), owner2:Person(id)) */
MATCH (owner1:Person|Company {_workspace_id:$workspace_id})-[:GUARANTEE]-(owner2:Person|Company {_workspace_id:$workspace_id})
WHERE owner1.id <> owner2.id
MATCH (owner1)-[:OWN]->(a1:Account {_workspace_id:$workspace_id})
MATCH (owner2)-[:OWN]->(a2:Account {_workspace_id:$workspace_id})
WHERE a1.acct_no < a2.acct_no
AND EXISTS { MATCH (a1)-[:TRANSFER]-(a2) }
AND EXISTS { MATCH (device:Medium {_workspace_id:$workspace_id})-[:SIGN_IN]->(a1), (device)-[:SIGN_IN]->(a2) }
RETURN a1.acct_no AS acct1, a2.acct_no AS acct2
LIMIT $limit

