/*+ USING JOIN ON owner */
CALL {
  MATCH (owner:Person {_workspace_id:$workspace_id})-[:OWN]->(a1:Account {_workspace_id:$workspace_id})
  MATCH (owner)-[:OWN]->(a2:Account {_workspace_id:$workspace_id})
  WHERE a1.id <> a2.id AND (a1)-[:TRANSFER]->(a2)
  RETURN a1.id AS id1, a2.id AS id2
}
